INSERT INTO `products` (`category_id`, `name`, `slug`, `product_code`, `price`, `sale_price`, `image`, `description`, `details`, `max_speed`, `battery_range`, `motor_power`, `warranty_months`, `stock`, `status`) VALUES
  ((SELECT id FROM categories WHERE slug = 'xe-may-dien' LIMIT 1), 'Kumatsu Benly', 'kumatsu-benly', 'KM-BENLY', 0.00, NULL, 'uploads/products/kumatsu-benly.jpg', 'Xe máy điện Kumatsu Benly: động cơ 500W, ắc quy 48V/20Ah, đi khoảng 60–80 km mỗi lần sạc, 3 chế độ lái Eco – Normal – Sport, phanh đĩa trước và sau.', '{"brand":"Kumatsu","variants":[{"name":"Benly (động cơ VS48V500WG)","price":null,"price_text":"≈ 15.900.000 ₫ (giá tạm)","colors":["Đen","Xanh","Đỏ"],"note":"Hãng bán các màu đen, xanh, đỏ…"}],"battery":{"type":"Ắc quy (tùy phiên bản)","voltage_capacity":"48V / 20Ah","range":"60–80 km mỗi lần sạc (tùy điều kiện vận hành)","charge_time":"6–10 giờ","warranty":"6 tháng (tạm)"},"spec_groups":[{"title":"Động cơ & vận hành","rows":[["Động cơ","VS48V500WG, công suất từ 500W"],["Bộ điều khiển","GOBAO 25A"],["Cách thao tác","Tự động"],["Vận tốc tối đa","40–50 km/h"],["Chế độ lái","Eco 1 – Normal 2 – Sport 3"],["Điện áp bảo vệ","42V ±1"],["Dòng điện bảo vệ","25A ±1"]]},{"title":"Kích thước & trọng lượng","rows":[["Dài × rộng × cao","1.670 × 705 × 1.050 mm"],["Chiều dài cơ sở","1.200 mm"],["Khối lượng bản thân","84 kg"],["Khả năng chở nặng","159 kg"],["Số người được chở","1 người"]]},{"title":"Khung gầm","rows":[["Lốp trước / sau","3.00-10 KENDA"],["Phanh","Đĩa trước và sau"],["Giảm xóc","Phuộc nhún trước và sau"]]},{"title":"Điện & tiện ích","rows":[["Hệ thống đèn","LED: đèn pha, đèn hậu, xi nhan"],["Màn hình","LCD điện tử: tốc độ, lượng pin, quãng đường"],["Chìa khóa","Smartkey: tìm xe, khóa/mở xe từ xa"],["Chống trộm","Cảnh báo khi có tác động bất thường"],["Cốp xe","Chứa áo mưa, đồ dùng cá nhân nhỏ"]]},{"title":"Chứng nhận & xuất xứ","rows":[["Nhãn hiệu / số loại","KUMATSU/BENLY"],["Xuất xứ","Việt Nam và liên doanh"],["Nhà sản xuất","Công ty TNHH TM và DV Việt Quang"],["Số chứng nhận","10327/VAQ06-01/25-00"]]}],"features":[{"icon":"tune","title":"3 chế độ lái","text":"Chọn Eco, Normal hoặc Sport theo điều kiện di chuyển."},{"icon":"key","title":"Chìa khóa thông minh","text":"Khóa, mở xe và tìm xe từ xa."},{"icon":"lock","title":"Chế độ chống trộm","text":"Cảnh báo khi xe bị tác động bất thường."},{"icon":"speed","title":"Màn hình LCD điện tử","text":"Xem tốc độ, lượng pin và quãng đường ngay trên xe."},{"icon":"lightbulb","title":"Đèn LED tiết kiệm điện","text":"Đèn pha, đèn hậu và xi nhan chiếu sáng rõ."},{"icon":"health_and_safety","title":"Phanh đĩa trước và sau","text":"Tăng độ an toàn khi phanh gấp."}],"warranty":{"summary":"Thời hạn bảo hành dưới đây là số liệu tạm, sẽ được xác nhận khi báo giá. Gọi {phone} để biết chính xác.","items":[["Bảo hành xe","12 tháng (tạm)"],["Bảo hành ắc quy / pin","6 tháng (tạm)"],["Bảo hành động cơ","12 tháng (tạm)"]],"aftersales":["Nhà sản xuất: Công ty TNHH TM và DV Việt Quang. Hotline hãng 0966053077 (bán hàng), 0989124920 (kỹ thuật).","Mua và bảo dưỡng tại Tiệp Anh: gọi {phone} hoặc đến {address}."]},"faq":[{"q":"Xe đi được bao xa sau mỗi lần sạc?","a":"Hãng công bố khoảng 60–80 km mỗi lần sạc, tùy điều kiện vận hành."},{"q":"Sạc đầy mất bao lâu?","a":"Khoảng 6–10 giờ, tùy phiên bản ắc quy."},{"q":"Xe chở được mấy người, tải trọng bao nhiêu?","a":"Xe cho phép chở 1 người, khả năng chở nặng 159 kg."},{"q":"Xe có những màu nào?","a":"Hãng bán các màu đen, xanh, đỏ… Gọi {phone} để biết màu còn hàng."},{"q":"Giá bán và thời gian bảo hành là bao nhiêu?","a":"Giá tạm khoảng 15,9 triệu đồng, bảo hành xe 12 tháng (số liệu tạm). Gọi {phone} để được báo giá chính xác."}],"sources":[{"label":"Trang xe Kumatsu Benly (xedienkumatsu.com)","url":"https://xedienkumatsu.com/benly-tr.html"}],"fetched_on":"03/10/2026"}', 50, 60, '500W', 12, 0, 'out_of_stock')
