  ((SELECT id FROM categories WHERE slug = 'xe-may-dien' LIMIT 1), 'Kumatsu VQ8', 'kumatsu-vq8', 'KM-VQ8', 0.00, NULL, 'uploads/products/kumatsu-vq8.jpg', 'Xe máy điện Kumatsu VQ8: động cơ 1000W không chổi than, hệ thống 60V, đi khoảng 60–80 km mỗi lần sạc, 3 chế độ tốc độ, mở khóa bằng chìa, remote hoặc thẻ NFC.', '{"brand":"Kumatsu","variants":[{"name":"VQ8 ắc quy chì axit (5 × 12V-20Ah)","price":null,"price_text":"≈ 19.900.000 ₫ (giá tạm)","colors":["Đen","Xanh","Đỏ","Cam"],"note":"Hãng ghi: đỏ đen, xanh dương, xám xi măng, cam xám…"},{"name":"VQ8 pin Lithium (tùy bản)","price":null,"price_text":"≈ 24.900.000 ₫ (giá tạm)","colors":["Đen","Xanh","Đỏ","Cam"],"note":"Bản pin Lithium: hỏi cửa hàng về bản đang có."}],"battery":{"type":"Ắc quy chì axit 5 × 12V-20Ah hoặc pin Lithium (tùy bản)","voltage_capacity":"60V","range":"60–80 km mỗi lần sạc","charge_time":"8–10 giờ (ắc quy) hoặc 4–6 giờ (pin Lithium)","warranty":"Ắc quy 6 tháng, pin Lithium 12 tháng (tạm)"},"spec_groups":[{"title":"Động cơ & vận hành","rows":[["Động cơ","1000W, không chổi than, chống nước IP67"],["Công suất lớn nhất","1,5 kW"],["Bộ điều khiển (IC)","30A, nhôm đúc, VS/60V12G"],["Chế độ lái (tốc độ)","Mức 1: 32 km/h · Mức 2: 40 km/h · Mức 3: 46 km/h"],["Tốc độ hãng công bố","Lên đến 50–55 km/h"],["Quãng đường di chuyển","60–80 km / lần sạc"]]},{"title":"Kích thước & trọng lượng","rows":[["Dài × rộng × cao","1.780 × 735 × 1.140 mm"],["Chiều dài cơ sở","1.285 mm"],["Khối lượng bản thân","95 kg"],["Khả năng chở nặng","225 kg"],["Số người được chở","1 người"]]},{"title":"Khung gầm","rows":[["Lốp trước / sau","3.50-10 KENDA"],["Phanh","Trước đĩa, sau tang trống"],["Giảm xóc","Dầu thủy lực trước và sau"],["Khung sườn","Thép chịu lực"]]},{"title":"Điện & tiện ích","rows":[["Hệ thống đèn","LED hoàn toàn (đèn pha, xi nhan)"],["Cách khởi động","Chìa khóa cơ, remote từ xa, thẻ NFC gần"],["Màn hình","LCD điện tử: tốc độ, pin, đèn báo, báo lỗi"],["Cốp xe","Đựng vừa mũ bảo hiểm nửa đầu và đồ cá nhân"]]},{"title":"Xuất xứ","rows":[["Nhãn hiệu / số loại","KUMATSU/VQ8"],["Xuất xứ","Việt Nam và liên doanh"],["Nhà sản xuất","Công ty TNHH TM và DV Việt Quang"]]}],"features":[{"icon":"electric_bolt","title":"Động cơ 1000W","text":"Động cơ không chổi than, vận hành êm và bền."},{"icon":"key","title":"Mở khóa 3 cách","text":"Dùng chìa khóa cơ, remote hoặc thẻ NFC."},{"icon":"speed","title":"3 mức tốc độ","text":"Chọn 32, 40 hoặc 46 km/h tùy đường đi."},{"icon":"monitor","title":"Màn hình LCD điện tử","text":"Xem tốc độ, pin, đèn báo và lỗi ngay trên xe."},{"icon":"water_drop","title":"Chống nước IP67","text":"Hãng nêu bảo vệ chống nước, chống chập."},{"icon":"inventory_2","title":"Cốp xe rộng","text":"Đựng vừa mũ bảo hiểm nửa đầu và đồ cá nhân."}],"warranty":{"summary":"Thời hạn bảo hành dưới đây là số liệu tạm, sẽ được xác nhận khi báo giá. Gọi {phone} để biết chính xác.","items":[["Bảo hành xe","12 tháng (tạm)"],["Bảo hành ắc quy / pin","6 tháng (tạm)"],["Bảo hành động cơ","12 tháng (tạm)"]],"aftersales":["Nhà sản xuất: Công ty TNHH TM và DV Việt Quang. Hotline hãng 0966053077.","Mua và bảo dưỡng tại Tiệp Anh: gọi {phone} hoặc đến {address}."]},"faq":[{"q":"Xe đi được bao xa sau mỗi lần sạc?","a":"Hãng công bố khoảng 60–80 km mỗi lần sạc."},{"q":"Sạc đầy mất bao lâu?","a":"Khoảng 8–10 giờ với ắc quy, 4–6 giờ với pin Lithium."},{"q":"Xe dùng ắc quy hay pin Lithium?","a":"Tùy bản: ắc quy chì axit 5 × 12V-20Ah hoặc pin Lithium. Gọi {phone} để biết bản đang có."},{"q":"Xe chở được mấy người, tải trọng bao nhiêu?","a":"Xe cho phép chở 1 người, khả năng chở nặng 225 kg."},{"q":"Giá bán và thời gian bảo hành là bao nhiêu?","a":"Giá tạm khoảng 19,9 triệu đồng (bản ắc quy) và 24,9 triệu đồng (bản pin Lithium), bảo hành xe 12 tháng (số liệu tạm). Gọi {phone} để được báo giá chính xác."}],"sources":[{"label":"Trang xe Kumatsu VQ8 (xedienkumatsu.com)","url":"https://xedienkumatsu.com/kumatsuvq8-xam-mo.html"}],"fetched_on":"03/10/2026"}', 46, 60, '1000W', 12, 0, 'out_of_stock')
INSERT INTO `products` (`category_id`, `name`, `slug`, `product_code`, `price`, `sale_price`, `image`, `description`, `details`, `max_speed`, `battery_range`, `motor_power`, `warranty_months`, `stock`, `status`) VALUES
  ((SELECT id FROM categories WHERE slug = 'xe-dap-dien' LIMIT 1), 'Sonco Lyn', 'sonco-lyn', 'SC-LYN', 0.00, NULL, 'uploads/products/sonco-lyn.jpg', 'Xe điện Sonco Lyn: động cơ 800W, hệ thống 60V (5 ắc quy 12V-20Ah), đi khoảng 70–80 km mỗi lần sạc, tốc độ tối đa 45–48 km/h, cốp xe 20 lít, kết nối ứng dụng Bluetooth.', '{"brand":"Sonco","variants":[{"name":"Sonco Lyn (800W, 60V)","price":null,"price_text":"12.990.000 ₫ (giá tham khảo của nhà phân phối)","colors":["Xám bóng","Đỏ đô","Trắng"],"note":"Màu tạm, hỏi cửa hàng màu còn hàng."}],"battery":{"type":"Ắc quy 5 bình 12V-20Ah","voltage_capacity":"60V (5 × 12V-20Ah)","range":"70–80 km mỗi lần sạc (tùy điều kiện vận hành)","charge_time":"6–8 giờ (tạm)","warranty":"12 tháng (lỗi đổi mới) — theo nhà phân phối nguồn, tham khảo"},"spec_groups":[{"title":"Động cơ & vận hành","rows":[["Động cơ","800W"],["Tốc độ tối đa","45–48 km/h"],["Quãng đường mỗi lần sạc","70–80 km (tùy điều kiện vận hành)"]]},{"title":"Pin & điện","rows":[["Ắc quy","5 bình 12V-20Ah (tổng 60V)"]]},{"title":"Khung gầm","rows":[["Phanh trước","Đĩa thủy lực"],["Phanh sau","Cơ (tang trống)"],["Giảm xóc","Phuộc thủy lực trước, lò xo đôi sau"],["Lốp","Không săm 3.00-10"]]},{"title":"Kích thước & tiện ích","rows":[["Trọng lượng","Khoảng 45 kg"],["Chiều cao yên","Khoảng 700 mm"],["Cốp xe","20 lít"],["Khóa","Khóa chống trộm thông minh"],["Màn hình","LCD màu"],["Ứng dụng","Bluetooth: khởi động không chìa, chống trộm, giới hạn tốc độ"]]}],"features":[{"icon":"smartphone","title":"Kết nối ứng dụng Bluetooth","text":"Khởi động không chìa, chống trộm và giới hạn tốc độ."},{"icon":"inventory_2","title":"Cốp xe 20 lít","text":"Có chỗ để đồ dùng cá nhân khi đi học, đi làm."},{"icon":"health_and_safety","title":"Phanh kép","text":"Phanh đĩa trước và phanh cơ sau để dừng xe an toàn."},{"icon":"monitor","title":"Màn hình LCD màu","text":"Theo dõi thông tin vận hành rõ ràng."},{"icon":"lock","title":"Khóa chống trộm thông minh","text":"Tăng an toàn khi gửi xe."},{"icon":"speed","title":"Giới hạn tốc độ","text":"Phù hợp người mới đi, học sinh (theo nhà phân phối nguồn)."}],"warranty":{"summary":"Theo nhà phân phối nguồn (tham khảo): động cơ 2 năm, ắc quy 1 năm (lỗi đổi mới). Chính sách của Tiệp Anh sẽ được xác nhận khi báo giá.","items":[["Bảo hành động cơ","24 tháng (tham khảo)"],["Bảo hành ắc quy","12 tháng, lỗi đổi mới (tham khảo)"],["Bảo hành khung","12 tháng (tạm)"]],"aftersales":["Hãng chưa có trang chính thức truy cập được, thông số lấy từ nhà phân phối: cần đối chiếu với xe thực tế.","Mua và bảo dưỡng tại Tiệp Anh: gọi {phone} hoặc đến {address}."]},"faq":[{"q":"Xe đi được bao xa sau mỗi lần sạc?","a":"Khoảng 70–80 km, tùy điều kiện vận hành."},{"q":"Tốc độ tối đa là bao nhiêu?","a":"Từ 45 đến 48 km/h."},{"q":"Xe dùng pin hay ắc quy?","a":"Xe dùng 5 bình ắc quy 12V-20Ah, tổng điện áp 60V."},{"q":"Xe có cốp để đồ không?","a":"Có, cốp xe dung tích khoảng 20 lít."},{"q":"Giá bán và thời gian sạc là bao nhiêu?","a":"Giá tham khảo từ 12.990.000 ₫, sạc đầy khoảng 6–8 giờ (số liệu tạm). Gọi {phone} để được báo giá chính xác."}],"sources":[{"label":"Xe đạp điện Sonco Lyn (xediennangtho.com)","url":"https://xediennangtho.com/xe-dap-dien-sonco-lyn/"}],"fetched_on":"03/10/2026"}', 48, 70, '800W', 12, 0, 'out_of_stock')
